{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Codeine, a 3-methoxy-N-methyl morphinan, has an absolute oral bioavailability of 42–71% in healthy volunteers, supporting that 3-O-methylation and N-methyl substitution confer adequate oral absorption despite morphinan first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Ethylmorphine, another 3-alkoxy-N-methyl morphinan, showed systemic availability of 54–92% (median 74%), supporting high oral bioavailability for the query's 3-methoxy/N-methyl scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nalmefene, a 14-hydroxy morphinan, has an absolute oral bioavailability of 41%, demonstrating that 14-hydroxy morphinans can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Samidorphan, a 14-hydroxy-6-keto morphinan, has an absolute oral bioavailability of 68.6%, directly supporting that a 6-keto/14-hydroxy morphinan can be highly bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Naltrexone, the closest analogue, has an absolute oral bioavailability of only 5%, but it differs from the query by a free 3-phenol and N-cyclopropylmethyl; the query's 3-methoxy group blocks phenolic glucuronidation, so this low-F result is not directly transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high: the query is a 3-methoxy-N-methyl-6-keto-14-hydroxy morphinan (oxycodone-like). High-F analogues sharing the 3-methoxy/N-methyl morphinan motif (codeine, ethylmorphine) and 14-hydroxy/6-keto morphinans (nalmefene, samidorphan) support F ≥20%; the closest low-F analogue naltrexone lacks the 3-methoxy group and is outweighed.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is present in the supplied evidence.",
    "Naltrexone low-F data are confounded by 3-phenol and N-cyclopropylmethyl differences relative to the query.",
    "Food effects and dose-dependent absorption for the query were not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

